def can_form_subsequence(s, t):
    t_idx = 0
    for char in s:
        if t_idx < len(t) and char == t[t_idx]:
            t_idx += 1
            if t_idx == len(t):
                return True
    return False

def solve(s, t):
    # Try to find the lexicographically smallest permutation of s that does not have t as a subsequence
    from itertools import permutations

    # Generate all permutations of s and sort lexicographically
    perms = [''.join(p) for p in permutations(s)]
    perms.sort()

    for perm in perms:
        if not can_form_subsequence(perm, t):
            return perm

    # This should not happen given the constraints
    return s

t = int(input())
for _ in range(t):
    s = input().strip()
    t_str = input().strip()
    print(solve(s, t_str))
